package com.digitalbase.ticketing.service;import com.digitalbase.ticketing.enums.ProductStatus; // Enum ကို Import လုပ်ရန်import com.digitalbase.ticketing.model.ClientProduct;import com.digitalbase.ticketing.repository.ClientProductRepository;import lombok.RequiredArgsConstructor;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.LocalDate;import java.time.ZoneId;import java.time.temporal.ChronoUnit;import java.util.Arrays;import java.util.List;@Service@RequiredArgsConstructorpublic class SlaExpirationJobService {    private final ClientProductRepository clientProductRepository;    // Notification (သို့) Email ပို့ရန် Service ကို ဤနေရာတွင် Inject လုပ်ပါ    // ည ၁၂ နာရီတိုင်း အလိုအလျောက် အလုပ်လုပ်မည်    @Scheduled(cron = "0 0 0 * * ?")    @Transactional    public void checkSlaExpirations() {        // ACTIVE နှင့် EXPIRING_SOON ဖြစ်နေသော Product နှစ်မျိုးလုံးကို ဆွဲထုတ်မည်        List<ProductStatus> workingStatuses = Arrays.asList(ProductStatus.ACTIVE, ProductStatus.EXPIRING_SOON);        List<ClientProduct> productsToCheck = clientProductRepository.findAllByStatusIn(workingStatuses);        LocalDate today = LocalDate.now();        for (ClientProduct cp : productsToCheck) {            if (cp.getPlanEndDate() == null) continue;            // Instant ကို LocalDate သို့ ပြောင်းလဲခြင်း            LocalDate endDate = cp.getPlanEndDate().atZone(ZoneId.systemDefault()).toLocalDate();            // ကျန်ရှိသော ရက်အရေအတွက် တွက်ချက်ခြင်း            long daysRemaining = ChronoUnit.DAYS.between(today, endDate);            if (daysRemaining <= 0) {                // သက်တမ်းကုန်သွားပါက ချက်ချင်း DISABLED (Read-Only) အဖြစ် ပြောင်းလဲလိုက်ပါမည်                cp.setStatus(ProductStatus.DISABLED);                clientProductRepository.save(cp);                sendWarningNotification(cp, "Your SLA Plan has expired. You now have read-only access. Please upgrade your plan.");            } else if (daysRemaining <= 7 && cp.getStatus() == ProductStatus.ACTIVE) {                // ၇ ရက်နှင့်အောက် ရောက်သွားလျှင် EXPIRING_SOON အဖြစ် အလိုအလျောက် ပြောင်းလဲမည်                cp.setStatus(ProductStatus.EXPIRING_SOON);                clientProductRepository.save(cp);                sendWarningNotification(cp, "Reminder: Your SLA Plan expires in " + daysRemaining + " days. Please renew to avoid service interruption.");            } else if (daysRemaining == 3 || daysRemaining == 1) {                // ၃ ရက် သို့မဟုတ် ၁ ရက် လိုပါက Notification သာ ထပ်ပို့မည် (Status သည် EXPIRING_SOON ဖြစ်နေပြီးသားပါ)                sendWarningNotification(cp, "Urgent: Your SLA Plan expires in " + daysRemaining + " days. Renew now to keep your access.");            }        }    }    private void sendWarningNotification(ClientProduct cp, String message) {        // ဤနေရာတွင် Customer ထံသို့ Email ပို့ခြင်း (သို့မဟုတ်) In-App Notification (ခေါင်းလောင်းလေး) ထဲသို့ စာဝင်သွားအောင် ရေးသားပါ        System.out.println("Sending to " + cp.getUser().getEmail() + " : " + message);    }}